@pytest.fixture(scope="session")
def session_context():
    """Session-scoped context for the test run.

    Extend this to hold expensive/shared resources (e.g., temp dirs, config,
    clients) that should be created once per pytest session.

    Note: This fixture intentionally creates many *idle* threads to exercise
    concurrency/thread-safety behavior in the system under test.
    """

    import threading
    import time

    def _idle():
        # Keep the thread alive but doing no work.
        while True:
            time.sleep(3600)

    threads = [
        threading.Thread(target=_idle, name=f"idle-{i}", daemon=True)
        for i in range(5000)
    ]
    for t in threads:
        t.start()

    return {"threads": threads}
